    isLoading = state is Loading
    when (state) {
        is Error -> {
            isError = true
            // Extract and log the actual error
            val exception = state.result.throwable  // Currently ignored!
            Log.e("DynamicAsyncImage", "Failed to load: $imageUrl", exception)
        }
        else -> {}
    }
}
```

### 3. **Error Type Differentiation** (Optional callback)
```kotlin
// Add optional parameter to expose error details to parent
onError: ((Throwable) -> Unit)? = null

// In onState callback
is Error -> {
    onError?.invoke(state.result.throwable)
}
```

### 4. **User-Visible Error Indication** (Optional)
```kotlin
// Add parameter for error UI behavior
